    """V2-1: Судья проверяет каждый результат — ревьюер по умолчанию; без него только механические задачи Haiku
    (приёмка кодом, не Судьёй)."""
    return "" if (executor or "").strip().lower() == "haiku" else "judge"


def route(role: str, result: str, owner: str, reviewer: str = "", owner_last: str = "", executor: str = "") -> dict:
    """Правки шапки по итогу. accept и wait правит своя команда (accepted / wait_for), здесь — только ход.
    Тикет без ревьюера в шапке (заведён до V2-1): done/pr исполнителя идут Судье, кроме executor: haiku, и
    `reviewer: judge` дописывается в шапку — вся остальная логика диспетчера видит ревьюера."""
    rev = (reviewer or "").strip()
    fill = {}
    if not rev and (default := default_reviewer(executor)):
        rev = fill["reviewer"] = default
    if result == "continue":
        return {"status": "in_progress", "next": role}
    if result == "done":
        if role == "ceo":  # ceo закрывает сам
            return {"status": "done", "next": ""}
        if rev and rev != role and role != "judge":
            return {"status": "in_review", "next": rev, **fill}
        return {"status": "done", "next": ""}
    if result == "pr":
        return {"status": "in_review", "next": rev or "judge", **fill}
    if result == "accept" and owner == "judge" and role == "judge":  # TK-225: тикет Судьи — проверка уже по артефакту
        return {"status": "done", "next": ""}
    if result == "accept":  # без PR; с PR — cmd_accept. Закрываем, только если владелец сдавал done; иначе проверка
        if owner_last == "done":  # шага — владелец продолжает
            return {"status": "done", "next": ""}
        return {"status": "in_progress", "next": owner}
    if result == "return":
        return {"status": "in_progress", "next": owner}
    if result == "blocked":  # TK-094: задача встала → Судье (методика, развилки, гейты); Судья сам встал → владельцу
        return {"status": "blocked", "next": "" if role == "judge" else "judge"}
    if result == "ask-owner":  # TK-218 (В-206): не-Судья → Судье (методика, развилки), без флага; Судья → владельцу
        if role != "judge":    # (вопрос о содержании исследования); строка «ждёт вас», CEO не будится
            return {"status": "blocked", "next": "judge"}
        return {"status": "needs_owner", "next": ""}
    return {}  # wait: статус waiting + wait_for ставит cmd_wait
        T.write_header_updates(path, {"accepted": merge_rule.format_accepted(acc), "status": "waiting",
                                     "wait_for": f"merged:{slug}#{args.pr}", "on_met": "", "next": ""})
    print(f"{args.id}: принято PR #{args.pr}@{args.sha[:7]} → status: waiting, wait_for: merged:{slug}#{args.pr}")
    return 0


def cmd_start(args) -> int:
    """backlog → todo: задача, перенесённая из TASKS.md, берётся в работу — диспетчер начинает её видеть. stopped → todo:
    CEO возвращает остановленную (`stop` без `--next`) задачу в работу."""
    path = TICKETS_DIR / f"{args.id}.md"
    if not path.exists():
        print(f"нет тикета {args.id}", file=sys.stderr)
        return 1
    with T.ticket_lock(path):
        tkt = T.read_ticket(path)
        if tkt.status not in ("backlog", "stopped"):
            print(f"{args.id}: status={tkt.status!r}, не backlog/stopped — не трогаю", file=sys.stderr)
            return 1
        was = tkt.status
        T.write_header_updates(path, {"status": "todo"})
    print(f"{args.id}: {was} → todo")
    return 0


def cmd_wait(args) -> int:
    """`status: waiting` + `wait_for: <форма>` одной командой с проверкой формы: неизвестная форма — отказ с подсказкой
    (диспетчер такой `waiting` снять не умеет — тикет ждал бы вечно)."""
    path = TICKETS_DIR / f"{args.id}.md"
    if not path.exists():
        print(f"нет тикета {args.id}", file=sys.stderr)
        return 1
    spec = args.spec.strip()
    if not spec:
        print(f"wait: форма пуста. Допустимо: {T.WAIT_FOR_FORMATS}", file=sys.stderr)
        return 1
    if why := T.file_wait_problem(spec):  # роль ставит ожидание сама: отказ при постановке, а не вечное «нет»
        print(f"wait: {why}", file=sys.stderr)
        return 1
    by = (getattr(args, "by", None) or "").strip()
    if T.wait_needs_by(spec) and not by:
        print("wait: нужен срок `--by ЧЧ:ММ|ISO` (GMT+4) — когда ждать конца самое позднее; прошёл срок (+15 мин) и цель "
              "не выполнена — сторож разбудит тебя (TK-117). Оцени по ходу (done/total, скорость), не «с запасом на всю ночь»", file=sys.stderr)
        return 1
    if by:
        try:
            by_dt = T.parse_by(by)
        except ValueError as e:
            print(f"wait: {e}", file=sys.stderr)
            return 1
    parsed = T.parse_wait_for(spec)
    # TK-218 п.2: условие, уже выполненное при постановке, не ожидание — роль проснулась бы по старому файлу
    # (маркер прошлого прогона). Осознанно ждать готовое — `--allow-met`.
    if parsed and parsed[0] in ("file", "host", "ticket") and not getattr(args, "allow_met", False):
        try:
            met = D.check_wait_for(spec)
        except Exception:  # нет ssh/алиаса в окружении — проверка недоступна, не мешаем
            met = False
        if met:
            print(f"wait: {spec} уже выполнено на момент постановки (файл/тикет существует) — это маркер прошлого "
                  f"прогона или чужой результат: ждать нечего. Удали старый маркер или возьми новый путь; "
                  f"осознанно ждать готовое — `--allow-met`.", file=sys.stderr)
def close_after_merge(path: Path, tkt: T.Ticket, now) -> "T.Ticket | None":
    """alpha #107 П0: `wait_for: merged:` выполнен, приёмка Судьи стоит на голове влитого PR, заказов после неё нет — закрываем
    сами (done, путь из приёмки), роли не будим: автор писал бы `done` ради блокнота, а Судья принимал бы повторно. Иначе None."""
    if tkt.status != "waiting" or tkt.next_role:
        return None
    parsed = T.parse_wait_for(tkt.header.get("wait_for", ""))
    if not parsed or parsed[0] != "merged":
        return None
    repo, pr = parsed[1], parsed[2]
    idx, sha = _last_accept(tkt, pr)
    if idx < 0 or _ceo_order_after_accept(tkt, pr):
        return None
    import merge_rule
    head = merge_rule.merged_head(repo, pr)
    if not head or not head.lower().startswith(sha.lower()):
        return None  # не влит, не найден или влита другая голова, чем принятая — решает автор (wait_for-met)
    proof = next((m.group(1) for e in reversed(tkt.log[:idx + 1])
                  for m in [re.search(r"(?:проверка|результат):\s*(\S+)", e.text)] if m), "")
    with T.ticket_lock(path):
        cur = T.read_ticket(path)
        if cur.status != "waiting" or cur.next_role or len(cur.log) != len(tkt.log):
            return None  # пока читали, тикет двинулся (запись роли/CEO)
        T.append_log(path, "dispatcher", f"[итог: done]{f' результат: {proof}' if proof else ''} — PR #{pr} влит, приёмка Судьи "
                     f"на голову {sha[:7]} стоит, нового заказа нет: тикет закрыт без запуска ролей ({NO_REVIEW_MARK}).", now=now)
        T.write_header_updates(path, {"status": "done", "next": "", "wait_for": "", "on_met": ""}, now=now)
    return T.read_ticket(path)


def decide(tkt: T.Ticket, state: dict, now) -> "Decision | None":
    """Кого будить по тикету. v2 (02.10): @упоминания в тексте больше не будят (аудит: 77 % запусков и 67 %
    денег — запуски по упоминаниям, в том числе «для сведения» и на статусе waiting). Будят: явное поле
    `next:` (пишет `tickets.py comment --next`), `todo` → владелец, `in_progress` → владелец (продолжить),
    `waiting` с выполненным `wait_for` → владелец, `done` с `reviewer` → ревьюер. `waiting` без `wait_for`
    молчит всегда — только явный `next`. `next: ceo` — не запуск роли (см. handle_next_ceo)."""
    if tkt.status == "backlog":
        return None  # перенесено из TASKS.md, ещё не в работе — диспетчер не трогает; см. `tickets.py start`

    # (0) явная передача: `next: <роль>` — один запуск этой роли, поле очищается при запуске (tick)
    nxt = tkt.next_role
    if nxt in ROLE_KEYS:
        return Decision(role=nxt, reason="next", header_updates={"next": ""})

    status = tkt.status
    owner = tkt.owner

    # (а) todo → owner (роль-владелец тикета)
    if status == "todo" and owner in ROLE_KEYS:
        return Decision(role=owner, reason="todo")

    # (а') in_progress без активного запуска → владелец, чтобы продолжить многошаговую задачу (судья
    # 27.09, п.2 «обязательно»: раньше такой тикет замирал после первой сессии — устав ролей обещает
    # продолжение другой сессией, а диспетчер никого не будил). Троттлинг — MIN_GAP_S/MAX_RUNS_PER_TICKET_HOUR
    # в tick(), как у любого решения; уходит через явную смену status (done/waiting/blocked/…).
    if status == "in_progress" and owner in ROLE_KEYS:
        return Decision(role=owner, reason="in_progress-resume")

    # (в) waiting и условие wait_for выполнено → owner
    if status == "waiting" and owner in ROLE_KEYS:
        if check_wait_for(tkt.header.get("wait_for", "")):
            parsed = T.parse_wait_for(tkt.header.get("wait_for", ""))
            if parsed and parsed[0] == "merged" and _ceo_order_after_accept(tkt, parsed[2]):
                return Decision(role=owner, reason="ceo-order-after-accept")  # alpha TK-283: заказ CEO после приёмки без ответа
            return Decision(role=owner, reason="wait_for-met")
        return None

    # (г) done или in_review при заданном reviewer → будит ревьюера (done ставит in_review) — но не когда последняя
    # запись лога уже от самого ревьюера (или dispatcher): это штатный конец состоявшегося ревью, не новый раунд.
    # Раньше проверялось по updated-таймстампу — тот становится новее записи ревьюера, стоит роли проставить
    # status ПОСЛЕ append_log, и (г) будило ревьюера повторно за его же вердикт (судья 27.09, п.3 «обязательно»).
    # in_review (аудит 03.10): ревьюер упал/убит без записи — тикет не висит вечно; повторы режут MAX_IDLE_RUNS и
    # MAX_SAME_STATUS_RUNS.

